import java.io.*;
import java.util.*;
import java.util.stream.*;

public class fivedimpoints {
    static int n;
    static int[][] coord;
    static boolean[] bad;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Iterator<String> tokens = br.lines()
                .flatMap(line -> Arrays.stream(line.split("\\s+")))
                .filter(s -> !s.isEmpty())
                .iterator();

        n = Integer.parseInt(tokens.next());
        if (n > 11) {
            System.out.println(0);
            return;
        }
        coord = new int[n][5];
        bad = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                coord[i][j] = Integer.parseInt(tokens.next());
            }
        }

        int count = n;
        for (int i = 0; i < n; i++) {
            if (hasPositiveDot(i)) {
                bad[i] = true;
                count--;
            }
        }
        System.out.println(count);
        for (int i = 0; i < n; i++) {
            if (!bad[i]) System.out.println(i + 1);
        }
    }

    static boolean hasPositiveDot(int i) {
        for (int j = 0; j < n; j++) {
            if (j == i) continue;
            for (int k = 0; k < n; k++) {
                if (k == i || k == j) continue;
                long prod = 0;
                for (int m = 0; m < 5; m++) {
                    long a = coord[j][m] - coord[i][m];
                    long b = coord[k][m] - coord[i][m];
                    prod += a * b;
                }
                if (prod > 0) return true;
            }
        }
        return false;
    }
}
